const userProfileQuery = `
	SELECT u.id, u.name, u.display_name, u.description, u.theme_id, u.dark_mode,
	       COALESCE(u.icon_hash, ?) AS icon_hash
	FROM users u`

type userProfile struct {
	UserModel
	ThemeID  int64  `db:"theme_id"`
	DarkMode bool   `db:"dark_mode"`
	IconHash string `db:"icon_hash"`
}

func (profile userProfile) user() User {
	return User{
		ID: profile.ID, Name: profile.Name, DisplayName: profile.DisplayName,
		Description: profile.Description, IconHash: profile.IconHash,
		Theme: Theme{ID: profile.ThemeID, DarkMode: profile.DarkMode},
	}
}

func loadUser(ctx context.Context, queries sqlx.QueryerContext, id int64) (User, error) {
	var profile userProfile
	if err := sqlx.GetContext(ctx, queries, &profile, userProfileQuery+" WHERE u.id = ? AND u.theme_id IS NOT NULL", fallbackImageHash, id); err != nil {
		return User{}, err
	}
	return profile.user(), nil
}

func loadUsers(ctx context.Context, tx *sqlx.Tx, ids []int64) (map[int64]User, error) {
	users := make(map[int64]User, len(ids))
	if len(ids) == 0 {
		return users, nil
	}

	query, args, err := sqlx.In(userProfileQuery+" WHERE u.id IN (?) AND u.theme_id IS NOT NULL", fallbackImageHash, ids)
	if err != nil {
		return nil, err
	}
	var rows []userProfile
	if err := tx.SelectContext(ctx, &rows, query, args...); err != nil {
		return nil, err
	}
	for _, row := range rows {
		users[row.ID] = row.user()
	}
	return users, nil
}

func fillLivestreams(ctx context.Context, tx *sqlx.Tx, models []*LivestreamModel) ([]Livestream, error) {
	streams := make([]Livestream, len(models))
	if len(models) == 0 {
		return streams, nil
	}

	ownerIDs := make([]int64, len(models))
	for i, model := range models {
		ownerIDs[i] = model.UserID
	}
	owners, err := loadUsers(ctx, tx, ownerIDs)
	if err != nil {
		return nil, err
	}

	for i, model := range models {
		owner, ok := owners[model.UserID]
		if !ok {
			return nil, sql.ErrNoRows
		}
		streams[i] = livestreamResponse(*model, owner)
	}
	return streams, nil
}

